import 'dotenv/config';
import cors from 'cors';
import express from 'express';
import { handleChat } from './chat';

const app = express();
const PORT = process.env.PORT ?? 3001;

app.use(cors());
app.use(express.json());

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', service: 'okvevo-agent' });
});

app.post('/chat', async (req, res) => {
  try {
    const { messages, userId, sessionId, model, videoUrl, pipelineMode, skillId, videoName } = req.body;
    const result = await handleChat(messages, userId, sessionId, model, videoUrl, pipelineMode, skillId, videoName);

    result.pipeUIMessageStreamToResponse(res, {
      headers: {
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
      onError: (error) =>
        error instanceof Error ? error.message : 'An error occurred.',
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    res.status(500).json({ error: message });
  }
});

app.listen(PORT, () => {
  console.log(`OkVevo Agent running on port ${PORT}`);
});
